node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get the next cart_item_id
const maxId = db.prepare(\"SELECT MAX(CAST(SUBSTR(cart_item_id, 4) AS INTEGER)) as max_id FROM cart_items\").get();
const nextNum = (maxId.max_id || 0) + 1;
const newItemId = 'CI-' + String(nextNum).padStart(4, '0');
console.log('New cart item ID:', newItemId);

// Get product price
const product = db.prepare('SELECT price FROM products WHERE product_id = ?').get('PROD-73FAB4');
console.log('Product price:', product.price);

// Insert new cart item
db.prepare('INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id) VALUES (?, ?, ?, ?, ?, ?, ?)').run(
  newItemId, 'CART-user_be7538d5', 'user_be7538d5', 'PROD-73FAB4', 1, 0, null
);

// Update cart totals
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_be7538d5');
const newSubtotal = cart.subtotal + product.price;
const newTotal = newSubtotal - cart.discount_amount + cart.gift_wrap_fee - cart.loyalty_discount + cart.shipping_cost;

// Update item_ids_json
const itemIds = JSON.parse(cart.item_ids_json);
itemIds.push(newItemId);

db.prepare('UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = ?').run(
  newSubtotal, newTotal, JSON.stringify(itemIds), 'CART-user_be7538d5'
);

// Verify
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_be7538d5');
const allItems = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all('CART-user_be7538d5');
console.log('\n=== UPDATED CART ===');
console.log(JSON.stringify(updatedCart, null, 2));
console.log('\n=== ALL CART ITEMS ===');
allItems.forEach(i => console.log(JSON.stringify(i, null, 2)));
"

